"use strict";
/* ======================================================================
   IBGE · RECENSEADOR (12º Censo Agropecuário, Florestal e Aquícola)
   Base de Conhecimentos Técnicos, tirada da apostila oficial
   "Conhecimentos básicos para o Censo Agropecuário, Florestal e Aquícola".
   Cada fato: [tópico, página, afirmação verdadeira, [versões falsas], comentário]
   ====================================================================== */
const IBGE_TOP_TEC={
 T01:{n:"IBGE: missão e rede de atendimento",d:"IBGE: fundado em 1936. 27 Superintendências Estaduais (26 nas capitais + 1 no DF) e 566 agências. Missão: retratar o Brasil com informações necessárias ao conhecimento de sua realidade e ao exercício da cidadania."},
 T02:{n:"Censo Agro: histórico, objetivos e abrangência",d:"1º Censo Agro: 1920. De 1940 a 1970: a cada 10 anos. Depois: 1975, 1980, 1985. 1990 não houve; veio em 1996. Século XXI: 2007 e 2017. Cerca de 5,1 milhões de estabelecimentos. Segue recomendações da FAO."},
 T03:{n:"Estrutura organizacional censitária",d:"Permanente: Sede (diretorias e coordenações) e SES. Temporária: CNQ (ligado à Sede), CEQ (ligado às SES) e Postos censitários. Cerca de 36 mil temporários em 2027."},
 T04:{n:"Atribuições: ACR, ACS, Recenseador e Posto",d:"Cadeia do posto: AOR → ACR → ACS → Recenseador. ACI e ACA apoiam o AOR. O Recenseador se reporta ao ACS. O ACS é o elo entre quem coleta e quem gerencia."},
 T05:{n:"Instrumentos de trabalho",d:"Mapa do Setor (descrição dos limites no verso), Descritivo do setor, Mapa Municipal Estatístico (MME, fixado no posto), DMC (tablet) e Manual do Recenseador. No DMC: mapa digital, Lista de Endereços (lista prévia) e questionários."},
 T06:{n:"Navegação: legenda, escala e imagem de satélite",d:"Nunca interprete um símbolo sem consultar a legenda. Escala 1:50.000 → 1 cm no mapa = 50.000 cm = 500 m. Na imagem de satélite observe forma, tamanho, localização e cores."},
 T07:{n:"Descritivo do setor e limites",d:"5 partes: 1) Ponto inicial e final; 2) Descrição do perímetro; 3) Setores a serem excluídos; 4) Estruturas territoriais não setorizadas; 5) Acessibilidade e observações. O recenseador NUNCA altera o perímetro."},
 T08:{n:"Divisão político-administrativa e geocódigo",d:"26 estados + DF; 5.569 municípios (lei estadual); 10.744 distritos (lei municipal); cerca de 645 subdistritos. Geocódigo: UF (2) + município (5) + distrito (2) + subdistrito (2) + setor (4) = 15 dígitos."},
 T09:{n:"Situação e tipos de setores censitários",d:"Situação = urbano × rural (forma de ocupação). Tipo = características especiais (acesso, procedimento). Agrupamento indígena/quilombola: 15 ou mais pessoas. Quartel, alojamento, prisão, convento/hospital/ILPI/IACA: 50 pessoas. Agrovila: mais de 50 domicílios."},
 T10:{n:"Povos e Comunidades Tradicionais e AIOs",d:"Pertencimento é AUTODECLARATÓRIO: registre o que o informante diz, sem questionar. AIOs não seguem a setorização (podem ser maiores ou menores que o setor). Acesso negociado com lideranças (Convenção 169 da OIT)."},
 T11:{n:"Endereço (padrão CNEFE)",d:"Componentes: logradouro, localidade, CEP, número e modificador, complemento, ponto de referência e coordenadas. Ponto de referência é obrigatório quando não há número nem complemento. Nunca identifique pessoas no endereço."},
 T12:{n:"Coordenadas geográficas",d:"Latitude: do Equador, 0° a 90°, Norte ou Sul (negativa = Sul). Longitude: de Greenwich, 0° a 180°, Leste ou Oeste (negativa = Oeste). Na área rural, captura manual na entrada da sede."},
 T13:{n:"Estabelecimento agropecuário: recenseável ou não",d:"Recenseável: produção para venda/troca OU subsistência. Não recenseável: produção só para lazer, pássaros/cães/gatos, animais de laboratório, hortos e estações experimentais, hotéis-fazenda, conventos, hospitais, escolas profissionalizantes, prisões. Quem classifica é o questionário de abordagem inicial."},
 T14:{n:"Atividades agropecuárias, florestais e aquícolas",d:"Lavoura temporária (milho, feijão, arroz, soja); permanente (café, laranja, uva); horticultura; hidroponia; criação de animais (incl. abelhas); aquicultura (peixes, camarões, moluscos, jacarés, rãs); exploração de matas (açaí, babaçu, buriti, celulose)."},
 T15:{n:"Produtores sem área",d:"Produzem sem área própria/delimitada: apicultor com colmeias em matas de terceiros, extrativista, criador em beira de estrada, quem produziu mas não estava mais na terra na data de referência. Aplica-se o questionário e marca-se o item de produtor sem área."},
 T16:{n:"Situações especiais",d:"Estabelecimento em mais de um setor: recenseia onde está a SEDE; sem sede, onde está a maior parte das terras. Áreas não contínuas = 1 estabelecimento só se: mesmo município + mesmos recursos técnicos + mesmo pessoal + mesma administração. Rio ou estrada cortando a terra não a torna descontínua."}
};
const IBGE_FATOS=[
/* T01 */
["T01",4,"O IBGE iniciou suas atividades em 1936.",["O IBGE iniciou suas atividades em 1920.","O IBGE iniciou suas atividades em 1940."],"A apostila informa que o IBGE existe desde 1936. Em 1920 foi feito o primeiro Censo Agropecuário, antes do IBGE."],
["T01",4,"O IBGE é o órgão coordenador e produtor de informações estatísticas e geográficas do País.",["O IBGE é o órgão responsável apenas pela produção de mapas, cabendo a outros órgãos as estatísticas.","O IBGE é um órgão estadual que produz informações apenas sobre a população urbana."],"Definição institucional (p. 4): órgão coordenador e produtor de informações estatísticas e geográficas."],
["T01",4,"A missão do IBGE é retratar o Brasil com informações necessárias ao conhecimento de sua realidade e ao exercício da cidadania.",["A missão do IBGE é fiscalizar a produção agropecuária e aplicar multas aos produtores.","A missão do IBGE é arrecadar tributos a partir dos dados coletados nos censos."],"Missão institucional transcrita na p. 4. O IBGE não fiscaliza nem arrecada."],
["T01",5,"A rede do IBGE é composta por 27 Superintendências Estaduais, sendo 26 nas capitais e 1 no Distrito Federal.",["A rede do IBGE é composta por 26 Superintendências Estaduais, todas nas capitais dos estados.","A rede do IBGE é composta por 27 Superintendências Estaduais, sendo 27 nas capitais e nenhuma no Distrito Federal."],"São 27 SES: 26 nas capitais + 1 no DF (p. 5)."],
["T01",5,"O IBGE conta com 566 agências municipais.",["O IBGE conta com 5.569 agências municipais, uma em cada município.","O IBGE conta com 645 agências municipais."],"566 agências (p. 5). 5.569 é o número de municípios; 645, o de subdistritos: pegadinha comum."],
["T01",5,"As Superintendências Estaduais e as agências são vinculadas à Presidência do IBGE.",["As Superintendências Estaduais são vinculadas aos governos estaduais.","As agências municipais são vinculadas às prefeituras."],"As unidades da rede são vinculadas à Presidência do Instituto (p. 5)."],
["T01",4,"As informações do IBGE afetam desde os preços no supermercado até políticas públicas de saúde, transporte e educação.",["As informações do IBGE têm uso restrito ao meio acadêmico.","As informações do IBGE não influenciam políticas públicas."],"A apostila destaca o impacto direto das informações na maneira como vivemos (p. 4)."],
/* T02 */
["T02",8,"O primeiro Censo Agropecuário do Brasil foi realizado em 1920.",["O primeiro Censo Agropecuário do Brasil foi realizado em 1936, ano de fundação do IBGE.","O primeiro Censo Agropecuário do Brasil foi realizado em 1940."],"1920: primeiro Censo Agro; 1936: fundação do IBGE (p. 8)."],
["T02",8,"De 1940 a 1970, os Censos Agropecuários foram realizados a cada dez anos.",["De 1940 a 1970, os Censos Agropecuários foram realizados a cada cinco anos.","De 1940 a 1970, os Censos Agropecuários foram realizados anualmente."],"Decenal de 1940 a 1970; a partir daí, quinquenal: 1975, 1980, 1985 (p. 8)."],
["T02",8,"Após 1970, os Censos Agropecuários passaram a ocorrer a cada cinco anos: 1975, 1980 e 1985.",["Após 1970, os Censos Agropecuários passaram a ocorrer a cada dez anos: 1980 e 1990.","Após 1970, os Censos Agropecuários passaram a ocorrer a cada três anos."],"Quinquenais: 1975, 1980, 1985 (p. 8)."],
["T02",8,"Em 1990 não foi possível realizar o Censo Agropecuário, que só ocorreu em 1996.",["Em 1990 o Censo Agropecuário foi realizado normalmente.","O Censo Agropecuário previsto para 1990 foi realizado em 1991."],"Pegadinha clássica: não houve censo em 1990; veio em 1996 (p. 8)."],
["T02",8,"No século XXI, foram realizados Censos Agropecuários em 2007 e em 2017.",["No século XXI, foram realizados Censos Agropecuários em 2006 e em 2016.","No século XXI, foi realizado apenas um Censo Agropecuário, em 2017."],"2007 e 2017 (p. 8)."],
["T02",8,"O Censo Agropecuário coleta dados com Dispositivos Móveis de Coleta (DMCs), mapas digitais e imagens de satélite.",["O Censo Agropecuário coleta dados exclusivamente em questionários de papel.","O Censo Agropecuário coleta dados apenas por telefone e internet."],"Coleta digital com DMC, mapas digitais e imagens de satélite (p. 8)."],
["T02",6,"Uma pesquisa censitária coleta os dados de toda a população do universo investigado; no Censo Agro, o universo é o dos estabelecimentos agropecuários.",["Uma pesquisa censitária coleta dados de uma amostra representativa do universo investigado.","No Censo Agro, o universo investigado é o dos domicílios rurais."],"Censo = todo o universo, não amostra (p. 6). Universo do Censo Agro: estabelecimentos agropecuários."],
["T02",9,"O 12º Censo Agro tem como objetivo levantar informações sobre todos os estabelecimentos agropecuários situados no território nacional.",["O 12º Censo Agro tem como objetivo levantar informações apenas sobre estabelecimentos com mais de 10 hectares.","O 12º Censo Agro tem como objetivo levantar informações apenas sobre estabelecimentos da área rural."],"Todos os estabelecimentos, independentemente de tamanho ou localização (p. 9)."],
["T02",9,"Espera-se produzir resultados sobre cerca de 5,1 milhões de estabelecimentos agropecuários.",["Espera-se produzir resultados sobre cerca de 51 milhões de estabelecimentos agropecuários.","Espera-se produzir resultados sobre cerca de 510 mil estabelecimentos agropecuários."],"Cerca de 5,1 milhões (p. 9). Em 2017 foram mais de 5 milhões visitados."],
["T02",9,"Um dos objetivos é estruturar um cadastro de estabelecimentos agropecuários para pesquisas amostrais.",["Um dos objetivos é estruturar um cadastro de contribuintes para a Receita Federal.","Um dos objetivos é cadastrar os produtores para a concessão automática de crédito rural."],"Cadastro para pesquisas amostrais (p. 9)."],
["T02",10,"A concepção do Censo segue recomendações da Estratégia Global para o Aprimoramento das Estatísticas Agropecuárias e do Programa Mundial de Censos Agropecuários da FAO.",["A concepção do Censo segue recomendações da OMS (Organização Mundial da Saúde).","A concepção do Censo segue recomendações do Banco Mundial e do FMI."],"FAO: Organização das Nações Unidas para Alimentação e Agricultura (p. 10)."],
["T02",10,"Os resultados são referidos ao nível dos Municípios e permitem análises por Terras Indígenas, Unidades de Conservação, Biomas e Projetos de Assentamento.",["Os resultados são divulgados apenas em nível nacional.","Os resultados são referidos apenas ao nível dos estados."],"Abrangência (p. 10)."],
["T02",10,"As informações do Censo possibilitam a avaliação de políticas públicas, como o Pronaf.",["As informações do Censo servem apenas para fins históricos, sem uso em políticas públicas.","O Pronaf é o programa responsável pela realização do Censo Agro."],"O Pronaf (Programa Nacional de Fortalecimento da Agricultura Familiar) é exemplo de política avaliada (p. 10)."],
["T02",10,"O Pronaf fomenta o desenvolvimento sustentável do meio rural e busca fortalecer os agricultores familiares.",["O Pronaf financia exclusivamente grandes empresas do agronegócio.","O Pronaf é um programa de fiscalização ambiental."],"Quadro do Pronaf (p. 10)."],
["T02",7,"Aquícola é o relativo à criação e à multiplicação de plantas e animais cujo ciclo de vida se dá total ou parcialmente em meio aquático.",["Aquícola é o relativo à pesca extrativa em alto-mar.","Aquícola é o relativo apenas à criação de peixes em rios naturais."],"Definição de aquícola (p. 7)."],
["T02",7,"Florestal é o relativo ao cultivo, manejo ou exploração de florestas e matas, nativas ou plantadas, incluindo o extrativismo florestal.",["Florestal é o relativo apenas a florestas plantadas, excluindo as nativas.","Florestal é o relativo apenas à preservação ambiental, sem exploração."],"Definição de florestal (p. 7)."],
["T02",7,"Agropecuário é o relativo às atividades de agricultura e pecuária, ou seja, à produção vegetal e à criação de animais.",["Agropecuário é o relativo apenas à criação de gado bovino.","Agropecuário é o relativo apenas às lavouras temporárias."],"Definição de agropecuário (p. 7)."],
/* T03 */
["T03",11,"Para o 12º Censo Agro, em 2027, serão contratados cerca de 36 mil profissionais temporários.",["Para o 12º Censo Agro serão contratados cerca de 360 mil profissionais temporários.","Para o 12º Censo Agro serão contratados cerca de 3,6 mil profissionais temporários."],"Cerca de 36 mil temporários por processo seletivo simplificado (p. 11)."],
["T03",11,"A estrutura censitária do 12º Censo Agro divide-se em estrutura permanente e estrutura temporária.",["A estrutura censitária divide-se em estrutura federal, estadual e municipal.","A estrutura censitária é inteiramente temporária."],"Duas estruturas: permanente e temporária (p. 11)."],
["T03",12,"A estrutura permanente está distribuída na Sede e nas Superintendências Estaduais, ambas ligadas à Presidência.",["A estrutura permanente está distribuída nos Postos censitários.","A estrutura permanente é formada pelo CNQ e pelo CEQ."],"Permanente: Sede + SES (p. 12). CNQ, CEQ e Postos são temporários."],
["T03",12,"O Centro Nacional de Qualidade (CNQ) é vinculado à Sede e monitora a qualidade dos dados em nível nacional.",["O Centro Nacional de Qualidade (CNQ) é vinculado às Superintendências Estaduais.","O CNQ é responsável pela coleta presencial dos dados."],"CNQ: Sede, nível nacional; composto por Analistas Censitários Nacionais e Agentes Censitários de Qualidade (p. 12)."],
["T03",13,"O Centro Estadual de Qualidade (CEQ) é vinculado às Superintendências Estaduais e monitora a qualidade em nível estadual.",["O Centro Estadual de Qualidade (CEQ) é vinculado diretamente à Presidência do IBGE.","O CEQ é formado pelos Recenseadores mais experientes."],"CEQ: SES, nível estadual (p. 13)."],
["T03",12,"No organograma, a COAGRO (Coordenação de Estatísticas Agropecuárias) está ligada à Diretoria de Pesquisas (DPE).",["A COAGRO está ligada à Diretoria de Geociências (DGC).","A COAGRO está ligada às Superintendências Estaduais."],"Organograma simplificado: Presidência → DPE → COAGRO → CNQ (p. 12)."],
["T03",13,"A equipe do Posto censitário é formada por AOR, ACA, ACI, ACR, ACS e Recenseadores.",["A equipe do Posto censitário é formada por Analistas Censitários Nacionais e Agentes de Qualidade.","A equipe do Posto censitário é formada apenas por Recenseadores e pelo Superintendente."],"Lista de servidores temporários do posto (p. 13)."],
["T03",13,"Os Postos censitários atendem a um município ou a um conjunto de municípios.",["Cada Posto censitário atende a um único setor censitário.","Cada Posto censitário atende a um estado inteiro."],"Base operacional que atende um ou mais municípios (p. 13)."],
["T03",14,"No posto, o AOR está acima do ACR, que está acima do ACS, que está acima do Recenseador.",["No posto, o ACS está acima do ACR, que está acima do AOR.","No posto, o Recenseador responde diretamente ao AOR."],"Cadeia: AOR → ACR → ACS → Recenseador (organograma p. 14)."],
["T03",15,"O Agente Censitário de Qualidade (ACQ) orienta ACS e Recenseadores na correção de erros e na necessidade de reforço de treinamento.",["O ACQ é responsável pela coleta presencial nos estabelecimentos.","O ACQ é responsável pela gestão administrativa do posto."],"Atribuição do ACQ (p. 15)."],
["T03",15,"O Analista Censitário Estadual tem nível superior e coordena os ACQ, conforme orientações dos analistas nacionais lotados no CNQ.",["O Analista Censitário Estadual é o responsável pela coleta em campo.","O Analista Censitário Estadual tem nível fundamental e atua no posto censitário."],"Analista Estadual (p. 15)."],
["T03",15,"Todo agente censitário deve ministrar treinamentos sempre que necessário e apoiar tarefas administrativas da operação.",["Somente o AOR pode ministrar treinamentos.","Os agentes censitários estão dispensados de tarefas administrativas."],"Regra geral ao final das funções (p. 15)."],
/* T04 */
["T04",15,"O AOR (Assistente Operacional Regional) é responsável por gerir o posto censitário.",["O AOR é responsável pela coleta presencial das informações.","O AOR é responsável apenas pelo suporte de informática."],"AOR gere o posto e garante que as instruções serão observadas (p. 15)."],
["T04",15,"O ACA (Agente Censitário Administrativo) apoia as atividades administrativas executadas pelo AOR.",["O ACA supervisiona diretamente os Recenseadores.","O ACA presta suporte de tecnologia da informação."],"ACA: apoio administrativo ao AOR (p. 15)."],
["T04",15,"O ACI (Agente Censitário de Informática) presta apoio relativo à tecnologia da informação ao AOR.",["O ACI é o responsável pelo treinamento dos Recenseadores.","O ACI gerencia a cobertura territorial do posto."],"ACI: apoio de TI (p. 15)."],
["T04",16,"O ACR é subordinado ao AOR e gerencia o trabalho dos Agentes Censitários Supervisores (ACS).",["O ACR é subordinado ao ACS e gerencia os AOR.","O ACR é subordinado diretamente ao Superintendente Estadual."],"ACR: subordinado ao AOR, gerencia ACS (p. 16)."],
["T04",16,"Entre as atribuições do ACR estão monitorar a cobertura e o cronograma da coleta e solucionar pendências da Supervisão de Qualidade.",["Entre as atribuições do ACR está aplicar pessoalmente todos os questionários do setor.","O ACR não tem atribuições ligadas à qualidade dos dados."],"Lista de atribuições do ACR (p. 16)."],
["T04",17,"O ACS supervisiona o trabalho dos Recenseadores e lhes ministra o treinamento.",["O ACS supervisiona o trabalho dos ACR.","O ACS é responsável pela gestão do posto censitário."],"ACS (p. 17)."],
["T04",17,"A função do ACS serve de elo entre aqueles que coletam as informações e aqueles que gerenciam o Posto censitário.",["A função do AOR serve de elo entre os Recenseadores e o ACS.","A função do Recenseador serve de elo entre o ACS e o ACR."],"ACS = elo (p. 17)."],
["T04",17,"O ACS gere e responde alertas no Sistema de Indicadores de Desempenho (SIGC).",["O Recenseador gere e responde alertas no SIGC.","O SIGC é o sistema de questionários usado pelo Recenseador no DMC."],"SIGC: atribuição do ACS (p. 17)."],
["T04",17,"O Recenseador realiza a coleta regular das informações, de modo presencial, em rotas diárias, sob a supervisão de um ACS.",["O Recenseador realiza a coleta por telefone, sob supervisão do AOR.","O Recenseador define livremente as próprias rotas, sem supervisão."],"Definição do Recenseador (p. 17)."],
["T04",18,"É ao ACS que o Recenseador deve se reportar sempre que encontrar alguma dificuldade ou dúvida.",["O Recenseador deve se reportar diretamente ao AOR em caso de dúvida.","O Recenseador deve resolver sozinho as dúvidas, consultando o informante."],"O Recenseador se reporta ao ACS (p. 18)."],
["T04",18,"O Recenseador deve agendar entrevistas, se solicitado pelo informante, e gerenciar sua realização.",["O Recenseador não pode agendar entrevistas; deve realizá-las na primeira visita.","O agendamento de entrevistas é feito exclusivamente pelo ACS."],"Atribuição do Recenseador (p. 18)."],
["T04",18,"Zelar pela integridade do DMC e pela confidencialidade das informações são atribuições do Recenseador.",["A confidencialidade das informações é responsabilidade exclusiva do CNQ.","O Recenseador pode compartilhar dados coletados com o informante vizinho."],"Atribuições do Recenseador (p. 18)."],
["T04",18,"Antes de iniciar a coleta, o Recenseador deve dedicar-se ao treinamento, realizando todas as atividades propostas.",["O Recenseador pode iniciar a coleta antes de concluir o treinamento.","O treinamento é opcional para quem já trabalhou em outro censo."],"Treinamento prévio obrigatório (p. 18)."],
["T04",19,"O Posto censitário é o local de trabalho criado temporariamente pelo IBGE para dar suporte à operação censitária.",["O Posto censitário é uma agência permanente do IBGE.","O Posto censitário é a residência do Recenseador."],"Definição de posto (p. 19)."],
["T04",19,"Caso a supervisão indique necessidade de corrigir algum dado coletado, o Recenseador deverá retornar a campo.",["Caso haja erro, o próprio supervisor corrige o dado sem retorno a campo.","Dados transmitidos não podem mais ser corrigidos."],"Retorno a campo para correção (p. 19)."],
/* T05 */
["T05",20,"O setor censitário é a menor área geográfica definida pelo IBGE e é a unidade territorial de coleta do Censo Agro.",["O município é a menor área geográfica definida pelo IBGE para a coleta.","O distrito é a unidade territorial de coleta do Censo Agro."],"Setor censitário: menor área e unidade de coleta (p. 20)."],
["T05",20,"No verso do Mapa do Setor Censitário consta a descrição dos seus limites.",["No verso do Mapa do Setor consta a lista de produtores do setor.","No verso do Mapa do Setor consta o questionário a ser aplicado."],"Verso do mapa: descrição dos limites (p. 20)."],
["T05",20,"O Mapa Municipal Estatístico (MME) fica fixado no posto e traz a visão geral de todos os setores do município e suas vias de acesso.",["O MME fica no DMC e mostra apenas o setor do Recenseador.","O MME é entregue ao produtor ao final da entrevista."],"MME: no posto, visão de todos os setores (p. 20)."],
["T05",20,"O MME deve ser usado para planejar a chegada ao setor.",["O MME deve ser usado para registrar as coordenadas do estabelecimento.","O MME substitui o descritivo na definição dos limites do setor."],"Uso do MME (p. 20)."],
["T05",21,"O Dispositivo Móvel de Coleta (DMC) é um tablet usado para registrar e armazenar as informações coletadas.",["O DMC é um computador fixo do posto censitário.","O DMC é um aparelho de GPS sem função de registro de dados."],"DMC (p. 21)."],
["T05",21,"A Lista de Endereços do DMC também é chamada de lista prévia.",["A Lista de Endereços do DMC também é chamada de lista definitiva.","A Lista de Endereços do DMC também é chamada de cadastro final."],"Lista prévia: vem de pesquisas anteriores e registros administrativos (p. 21)."],
["T05",21,"O Recenseador deve visitar todos os endereços de estabelecimentos do setor, mesmo os que não estejam na lista prévia.",["O Recenseador deve visitar apenas os endereços que constam na lista prévia.","Endereços fora da lista prévia devem ser ignorados."],"Cobertura completa, além da lista (p. 21)."],
["T05",21,"Para atualizar a lista prévia, o Recenseador confirma endereços existentes, inclui novos e exclui os não encontrados.",["Para atualizar a lista prévia, o Recenseador apenas confirma os endereços existentes.","O Recenseador não pode excluir endereços da lista prévia."],"Confirmar, incluir, excluir (p. 21)."],
["T05",21,"No mapa digital do DMC, os limites do setor são destacados com cor adequada para diferenciá-lo das demais áreas.",["O mapa digital do DMC não mostra os limites do setor.","O mapa digital mostra apenas o setor, sem as áreas ao redor."],"Mapa digital com áreas ao redor e limites destacados (p. 21)."],
["T05",21,"Entre os quesitos do questionário estão identificação do estabelecimento, do produtor, da produção, área e uso das terras.",["O questionário investiga apenas a renda familiar do produtor.","O questionário não investiga a área do estabelecimento."],"Quesitos do questionário (p. 21–22)."],
["T05",22,"O Manual do Recenseador é usado no treinamento e serve de fonte de consulta durante o trabalho de campo.",["O Manual do Recenseador é usado apenas após o fim da coleta.","O Manual do Recenseador substitui o treinamento presencial."],"Manual (p. 22)."],
/* T06 */
["T06",24,"Nunca se deve interpretar um símbolo no mapa sem antes consultar a legenda.",["A legenda é dispensável quando há imagem de satélite.","A legenda serve apenas para indicar a escala do mapa."],"Destaque da p. 24."],
["T06",24,"Escala é a relação de proporção entre a distância representada no mapa e a distância real no terreno.",["Escala é a relação entre a área do setor e o número de estabelecimentos.","Escala é a relação entre latitude e longitude."],"Definição de escala (p. 24)."],
["T06",24,"Na escala 1:50.000, 1 cm no mapa corresponde a 50.000 cm (500 m) no terreno.",["Na escala 1:50.000, 1 cm no mapa corresponde a 50 km no terreno.","Na escala 1:50.000, 1 cm no mapa corresponde a 5.000 m no terreno."],"50.000 cm = 500 m (p. 24)."],
["T06",25,"Na escala 1:50.000, 3 cm no mapa correspondem a 1,5 km no terreno.",["Na escala 1:50.000, 3 cm no mapa correspondem a 15 km no terreno.","Na escala 1:50.000, 3 cm no mapa correspondem a 150 m no terreno."],"3 × 50.000 = 150.000 cm = 1.500 m = 1,5 km (p. 25)."],
["T06",25,"Uma forma rápida de usar a escala gráfica é medir a distância com os dedos na escala e transferi-la para o trecho desejado.",["A escala gráfica só pode ser usada com régua milimetrada.","A escala gráfica não permite estimar distâncias."],"Técnica dos dedos (p. 25)."],
["T06",26,"Antes de sair para o campo, deve-se observar a escala do mapa para planejar o deslocamento.",["A escala só precisa ser observada depois de chegar ao setor.","Em setores rurais, a escala não é relevante."],"Destaque da p. 26."],
["T06",26,"Na interpretação de imagens de satélite, observam-se forma, tamanho, localização e cores dos elementos.",["Na interpretação de imagens de satélite, observam-se apenas as cores.","Imagens de satélite não ajudam a identificar galpões e plantações."],"Quatro características (p. 26–27)."],
["T06",26,"Rotatórias costumam aparecer como círculos nas imagens de satélite (característica de forma).",["Rotatórias aparecem como linhas retas nas imagens de satélite.","A forma não ajuda a reconhecer elementos na imagem."],"Exemplo de forma (p. 26)."],
["T06",27,"Na imagem de satélite, pastagens aparecem em tons de verde e telhados em vermelho, laranja, cinza ou branco.",["Na imagem de satélite, pastagens aparecem em tons de azul.","Telhados aparecem sempre em verde nas imagens."],"Exemplo de cores (p. 27)."],
["T06",27,"Endereço identificado pela imagem ou em campo, mas ausente da lista, deve ser visitado e registrado no DMC.",["Endereço ausente da lista deve ser ignorado.","Endereço visto só na imagem deve ser registrado sem visita."],"p. 27."],
["T06",50,"Confiar exclusivamente no GPS ou deixar de usar o mapa em papel são erros que devem ser evitados.",["O GPS dispensa o uso do mapa em papel.","O mapa em papel deve ser usado apenas quando o GPS falhar."],"Destaque da p. 50."],
/* T07 */
["T07",28,"O descritivo do setor censitário é composto de cinco partes.",["O descritivo do setor censitário é composto de três partes.","O descritivo do setor censitário é composto de sete partes."],"Cinco partes (p. 28)."],
["T07",28,"O ponto inicial geralmente é de fácil acesso; se não for possível, o recenseador pode adotar outro ponto, comunicando o Supervisor.",["O recenseador nunca pode adotar outro ponto inicial.","O recenseador pode mudar o ponto inicial sem avisar ninguém."],"Ponto inicial e final (p. 28)."],
["T07",28,"A descrição do perímetro é o texto que descreve todo o limite do setor, a partir das linhas que limitam suas bordas.",["A descrição do perímetro lista os produtores do setor.","A descrição do perímetro indica a quantidade de estabelecimentos."],"Descrição do perímetro (p. 28)."],
["T07",29,"Setores rurais são frequentemente limitados por corpos hídricos, como rios, córregos, igarapés e lagoas.",["Setores rurais nunca são limitados por rios.","Corpos hídricos não podem servir de limite de setor."],"Limite tipo A (p. 29)."],
["T07",29,"Rodovias, estradas e ferrovias, asfaltadas ou não, são delimitadores frequentes de setores.",["Apenas rodovias federais asfaltadas podem servir de limite de setor.","Ferrovias não são usadas como limite de setor."],"Limite tipo B (p. 29)."],
["T07",29,"Caminhos, ramais e estradas secundárias também são usados como limites, por serem fáceis de identificar em campo.",["Caminhos e ramais não podem ser usados como limites.","Estradas secundárias só servem de limite se forem pavimentadas."],"Limite tipo C (p. 29)."],
["T07",29,"Linhas secas são limites retos não materializados no terreno, que podem ligar pontos de referência visíveis.",["Linhas secas são rios temporários que secam no verão.","Linhas secas são estradas de terra sem pavimentação."],"Limite tipo D (p. 29). Pegadinha: não é rio seco."],
["T07",30,"O recenseador não pode alterar o perímetro do setor em hipótese alguma.",["O recenseador pode alterar o perímetro se encontrar um limite difícil de identificar.","O recenseador pode ampliar o perímetro para incluir estabelecimentos vizinhos."],"Regra absoluta (p. 30)."],
["T07",30,"Se houver inconsistência ou dificuldade para identificar o limite, o recenseador deve comunicar imediatamente a supervisão.",["Se houver dificuldade com o limite, o recenseador deve escolher o limite que achar mais lógico.","Inconsistências de limite devem ser ignoradas."],"p. 30."],
["T07",30,"Setores a serem excluídos são setores contidos dentro do perímetro do seu setor que não fazem parte de sua responsabilidade.",["Setores a serem excluídos são setores sem estabelecimentos agropecuários.","Setores a serem excluídos devem ser recenseados pelo mesmo recenseador ao final."],"Parte 3 (p. 30). Outro recenseador cuidará deles."],
["T07",31,"Estruturas territoriais não setorizadas, como aglomerados rurais pequenos, devem ser recenseadas normalmente dentro do setor.",["Estruturas territoriais não setorizadas não devem ser recenseadas.","Estruturas territoriais não setorizadas são recenseadas pelo ACS."],"Parte 4 (p. 31)."],
["T07",31,"O item Acessibilidade e Observações registra informações sobre o acesso e o percurso, como restrições de acesso fluvial.",["O item Acessibilidade e Observações lista os produtores ausentes.","O item Acessibilidade e Observações traz o geocódigo do setor."],"Parte 5 (p. 31)."],
["T07",30,"A correta observação do perímetro garante que o recenseador não invada outro setor nem omita parte do seu.",["Invadir setor vizinho não causa problema à coleta.","O perímetro serve apenas como referência aproximada."],"p. 30."],
/* T08 */
["T08",32,"O Brasil possui 26 estados e o Distrito Federal.",["O Brasil possui 27 estados e o Distrito Federal.","O Brasil possui 26 estados, sem contar o Distrito Federal como UF."],"26 + DF (p. 32–33)."],
["T08",32,"O Brasil possui 5.569 municípios.",["O Brasil possui 5.570 municípios.","O Brasil possui 10.744 municípios."],"5.569 municípios (p. 32). 10.744 é o número de distritos."],
["T08",32,"Municípios são criados, incorporados, fundidos ou desmembrados por lei estadual.",["Municípios são criados por lei municipal.","Municípios são criados por decreto do IBGE."],"Lei estadual (p. 32)."],
["T08",32,"Distritos são criados por legislação municipal e não possuem autonomia administrativa.",["Distritos são criados por lei estadual e possuem autonomia administrativa.","Distritos são criados pelo IBGE para fins estatísticos."],"Lei municipal, sem autonomia (p. 32)."],
["T08",33,"Existem cerca de 10.744 distritos no Brasil.",["Existem cerca de 5.569 distritos no Brasil.","Existem cerca de 645 distritos no Brasil."],"10.744 distritos (p. 33)."],
["T08",33,"Existem aproximadamente 645 subdistritos, e a maior parte dos municípios não os possui.",["Todos os municípios brasileiros possuem subdistritos.","Existem aproximadamente 10.744 subdistritos."],"Subdistritos: geralmente em grandes cidades (p. 33)."],
["T08",33,"Fernando de Noronha é um distrito estadual.",["Fernando de Noronha é um município do Rio Grande do Norte.","Fernando de Noronha é um território federal."],"Figura da p. 33: 1 Distrito Estadual (Fernando de Noronha)."],
["T08",34,"O geocódigo do setor reúne UF, município, distrito, subdistrito e número do setor, identificando-o de forma única.",["O geocódigo do setor reúne apenas o código da UF e do município.","O geocódigo do setor é o CEP da sede do setor."],"Geocódigo (p. 34)."],
["T08",34,"No geocódigo 51 04104 05 00 0016, o código 0016 identifica o setor.",["No geocódigo 51 04104 05 00 0016, o código 0016 identifica o distrito.","No geocódigo 51 04104 05 00 0016, o código 0016 identifica o município."],"UF 51, município 04104, distrito 05, subdistrito 00, setor 0016 (p. 34)."],
["T08",34,"O geocódigo aparece no título e no rodapé dos mapas e no canto superior direito do Descritivo do Setor.",["O geocódigo aparece apenas no questionário.","O geocódigo não aparece no Descritivo do Setor."],"p. 34."],
["T08",33,"Os setores são planejados com dimensões adequadas ao trabalho e respeitando a divisão político-administrativa.",["Os setores podem atravessar limites de municípios livremente.","Os setores são definidos pelo próprio Recenseador."],"p. 33."],
/* T09 */
["T09",35,"Os setores são classificados por dois códigos: situação e tipo.",["Os setores são classificados por um único código: o tipo.","Os setores são classificados por situação, tipo e bioma."],"Situação e tipo (p. 35)."],
["T09",35,"A situação classifica o setor como urbano ou rural, segundo a forma de ocupação do espaço.",["A situação indica restrições de acesso ao setor.","A situação indica o número de estabelecimentos do setor."],"Situação = urbano/rural (p. 35)."],
["T09",35,"O tipo está associado a características específicas do território, como restrições de acesso e procedimentos diferenciados.",["O tipo indica apenas se o setor é urbano ou rural.","O tipo indica o tamanho do setor em hectares."],"Tipo (p. 35)."],
["T09",36,"Aglomerado rural: domicílios normalmente a no máximo 50 m entre si e separados das cidades e vilas por mais de 1 km.",["Aglomerado rural: domicílios a no máximo 500 m entre si e a menos de 1 km da cidade.","Aglomerado rural: domicílios a mais de 1 km entre si."],"Definição (p. 36)."],
["T09",36,"Núcleo urbano: aglomeração separada das cidades e vilas por menos de 1 km ou que, mesmo mais distante, tem características urbanas.",["Núcleo urbano: aglomeração a mais de 1 km da cidade, sempre sem características urbanas.","Núcleo urbano é sinônimo de aglomerado rural."],"Definição (p. 36). Pegadinha: confundir com aglomerado rural."],
["T09",36,"Massas d'água são grandes porções de água que não são áreas de coleta, mas podem interferir na operação.",["Massas d'água são setores de coleta de aquicultura obrigatória.","Massas d'água são áreas urbanas de baixa densidade."],"p. 36."],
["T09",36,"Setores de tipo especial só são visitados no Censo Agro se tiverem produção agropecuária, florestal ou aquícola.",["Setores de tipo especial nunca são visitados no Censo Agro.","Setores de tipo especial são sempre visitados, com ou sem produção."],"p. 36."],
["T09",37,"Setor de tipo Quartel e Base Militar exige pelo menos 50 habitantes permanentes residindo há mais de um ano.",["Setor de tipo Quartel e Base Militar exige pelo menos 15 habitantes permanentes.","Setor de tipo Quartel e Base Militar exige pelo menos 500 habitantes."],"50 habitantes, mais de 1 ano (p. 37)."],
["T09",37,"Agrupamento Indígena: 15 ou mais indivíduos indígenas em moradias contíguas e com vínculos familiares ou comunitários.",["Agrupamento Indígena: 50 ou mais indivíduos indígenas.","Agrupamento Indígena: 5 ou mais domicílios indígenas."],"15 ou mais (p. 37)."],
["T09",38,"Agrupamento Quilombola: 15 ou mais indivíduos autodeclarados quilombolas em moradias contíguas.",["Agrupamento Quilombola: 50 ou mais indivíduos quilombolas.","Agrupamento Quilombola dispensa a autodeclaração."],"15 ou mais, autodeclarados (p. 38)."],
["T09",37,"Unidade prisional: setor relacionado a unidades que abrigam mais de 50 presos permanentes.",["Unidade prisional: setor com mais de 15 presos permanentes.","Unidade prisional: setor com mais de 500 presos."],"Mais de 50 presos (p. 37)."],
["T09",38,"Agrovila: setor com mais de 50 domicílios associados a Projetos de Assentamento, importante para o Censo Agro.",["Agrovila: setor com mais de 15 domicílios em área urbana.","Agrovila é um setor sem estabelecimentos agropecuários."],"p. 38."],
["T09",38,"ILPI é a sigla que substituiu o termo asilo, e IACA substituiu o termo orfanato.",["ILPI substituiu o termo orfanato, e IACA substituiu asilo.","ILPI e IACA são tipos de setor de assentamento rural."],"Instituição de Longa Permanência para Idosos / Instituição de Acolhimento de Crianças e Adolescentes (p. 38)."],
["T09",37,"Setor com Baixo Patamar Domiciliar abrange baixa quantidade de domicílios ou nenhum domicílio identificado.",["Setor com Baixo Patamar Domiciliar é aquele com renda baixa.","Setor com Baixo Patamar Domiciliar é aquele com prédios de poucos andares."],"p. 37."],
["T09",37,"Acampamento é instalação improvisada (barracas, tendas) e deve ter no mínimo 50 habitantes residindo há mais de um ano.",["Acampamento é qualquer instalação com pelo menos 15 pessoas.","Acampamento é um domicílio coletivo de universidade."],"p. 37. Alojamento é que costuma ser ligado a universidades ou empresas."],
["T09",35,"Os setores mais trabalhados no Censo Agro são áreas rurais de ocupação dispersa, aglomerados rurais e áreas urbanas de baixa densidade.",["Os setores mais trabalhados no Censo Agro são áreas urbanas de alta densidade.","O Censo Agro não trabalha em áreas urbanas."],"p. 35."],
/* T10 */
["T10",39,"Povos e Comunidades Tradicionais são grupos culturalmente diferenciados, que se reconhecem como tais e usam territórios e recursos naturais para sua reprodução cultural, social e econômica.",["Povos e Comunidades Tradicionais são definidos apenas por critério de renda.","Povos e Comunidades Tradicionais são apenas os povos indígenas."],"Definição (p. 39)."],
["T10",40,"O pertencimento étnico é autodeclaratório: registra-se a declaração do informante, sem questionamentos nem correções.",["O recenseador deve corrigir a declaração quando discordar dela.","O pertencimento étnico é definido pela aparência do informante."],"p. 40. Pegadinha frequente."],
["T10",40,"Uma mesma pessoa pode se reconhecer como pertencente a mais de uma comunidade tradicional.",["Cada pessoa só pode declarar pertencer a uma comunidade tradicional.","A multiplicidade de identidades não é aceita no Censo."],"Multiplicidade de identidades (p. 40)."],
["T10",40,"Terras Indígenas e Territórios Quilombolas oficialmente delimitados são territórios oficialmente reconhecidos pelo Estado.",["Terras Indígenas oficialmente delimitadas são agrupamentos identificados pelo IBGE.","Territórios Quilombolas são Áreas de Interesse Operacional."],"Tabela de categorias (p. 40)."],
["T10",40,"Agrupamentos Indígenas e Quilombolas são agrupamentos identificados pelo IBGE.",["Agrupamentos Indígenas são territórios oficialmente reconhecidos pelo Estado.","Agrupamentos Quilombolas são delimitados pela FUNAI."],"Tabela (p. 40)."],
["T10",41,"As Áreas de Interesse Operacional (AIOs) indicam presença efetiva ou potencial de povos e comunidades tradicionais e não seguem a setorização.",["As AIOs coincidem sempre com os limites de um setor censitário.","As AIOs são setores urbanos de alta densidade."],"AIOs (p. 41)."],
["T10",41,"Uma AIO pode ser menor ou maior que um setor, podendo cobrir até um município inteiro.",["Uma AIO nunca ultrapassa o limite de um setor.","Uma AIO é sempre menor que um distrito."],"p. 41."],
["T10",41,"Se o setor pertence a uma AIO, ela é carregada automaticamente no mapa digital e perguntas específicas aparecem no DMC.",["O recenseador deve desenhar a AIO manualmente no DMC.","As perguntas específicas de PCTs são feitas em papel."],"p. 41."],
["T10",41,"Nas áreas de PCTs, as condições de acesso são negociadas previamente com lideranças, associações e órgãos parceiros.",["Nas áreas de PCTs, o recenseador entra sem aviso prévio.","O acesso a áreas de PCTs é proibido ao IBGE."],"p. 41."],
["T10",42,"A Convenção nº 169 da OIT determina a consulta aos povos e comunidades tradicionais sempre que ações possam afetá-los diretamente.",["A Convenção nº 169 da ONU proíbe pesquisas em terras indígenas.","A Convenção nº 169 da OIT trata do salário mínimo rural."],"OIT (Organização Internacional do Trabalho), p. 42."],
["T10",42,"Segundo o Censo Demográfico 2022, apenas 67,1% dos indígenas em terras indígenas falam português no domicílio.",["Segundo o Censo 2022, 97,1% dos indígenas em terras indígenas falam português no domicílio.","Segundo o Censo 2022, apenas 17,6% dos indígenas falam português."],"67,1% (p. 42)."],
["T10",42,"O guia-intérprete é indicado com apoio da FUNAI e da SESAI.",["O guia-intérprete é indicado pela prefeitura municipal.","O guia-intérprete é escolhido pelo próprio recenseador."],"FUNAI e SESAI (p. 42)."],
["T10",39,"Raizeiros, quebradeiras de coco-babaçu e catadores de mangaba são exemplos de extrativistas entre os PCTs.",["Raizeiros e quebradeiras de coco-babaçu não são considerados PCTs.","Catadores de mangaba são classificados como pescadores artesanais."],"Lista de PCTs (p. 39)."],
["T10",40,"Caiçaras, vazanteiros, pantaneiros, retireiros e fundos e fechos de pasto também estão entre os PCTs citados.",["Caiçaras e pantaneiros não estão entre os PCTs citados pela apostila.","Fundos e fechos de pasto são tipos de setor censitário."],"Lista (p. 40)."],
/* T11 */
["T11",43,"O endereço segue o padrão do Cadastro Nacional de Endereços para Fins Estatísticos (CNEFE).",["O endereço segue o padrão do Cadastro Ambiental Rural (CAR).","O endereço segue exclusivamente o padrão dos Correios."],"CNEFE (p. 43)."],
["T11",43,"Prioriza-se o endereço formal e, na sua ausência, referências localmente reconhecidas.",["Prioriza-se sempre o nome popular, mesmo havendo endereço formal.","Sem endereço formal, o estabelecimento não é registrado."],"p. 43."],
["T11",43,"Logradouro é uma área pública de circulação de pessoas, veículos e mercadorias, reconhecida pela comunidade.",["Logradouro é o nome do proprietário do estabelecimento.","Logradouro é o nome do povoado onde fica o endereço."],"p. 43. O povoado é a localidade."],
["T11",44,"O logradouro deve ser registrado sem omissão de termos e sem abreviações.",["O logradouro deve ser abreviado para caber no campo.","O logradouro pode omitir o tipo (rua, estrada etc.)."],"p. 44."],
["T11",44,"Um rio pode ser registrado como logradouro.",["Um rio nunca pode ser logradouro.","Somente vias asfaltadas podem ser logradouros."],"Ex.: Rio Imperador (p. 44)."],
["T11",44,"Localidade é o nome do local ou região; na área rural indica povoados, assentamentos e comunidades, e na urbana assemelha-se ao bairro.",["Localidade é o número da casa no logradouro.","Localidade é o CEP do endereço."],"p. 44."],
["T11",45,"O CEP é mantido pela Empresa Brasileira de Correios e Telégrafos e tem oito dígitos.",["O CEP é mantido pelo IBGE e tem sete dígitos.","O CEP tem dez dígitos e é definido pela prefeitura."],"p. 45."],
["T11",46,"O modificador é alfanumérico e diferencia posições com a mesma numeração (ex.: 4573 B).",["O modificador é o nome do bairro.","O modificador é sempre um número."],"p. 46."],
["T11",46,"Complemento diferencia unidades com a mesma posição no logradouro, como lote, gleba, casa, fundos, sala.",["Complemento é o nome do rio mais próximo.","Complemento é o nome do produtor."],"p. 46."],
["T11",47,"O ponto de referência é obrigatório quando o endereço não possui número nem complemento que permita localizá-lo.",["O ponto de referência é proibido em áreas rurais.","O ponto de referência deve ser sempre preenchido, mesmo quando redundante."],"p. 47. Não deve ser usado de forma redundante."],
["T11",47,"Não é permitido identificar pessoas nos componentes do endereço, pois isso fere o sigilo estatístico.",["É recomendado usar o nome do produtor como ponto de referência.","O nome do morador pode ser usado como complemento."],"Destaque da p. 47. Pegadinha frequente."],
/* T12 */
["T12",48,"Latitude é o afastamento, em graus, da linha do Equador; vai de 0° a 90°, Norte ou Sul.",["Latitude é o afastamento do meridiano de Greenwich; vai de 0° a 180°.","Latitude vai de 0° a 180°, Leste ou Oeste."],"p. 48."],
["T12",48,"Longitude é o afastamento, em graus, do meridiano de Greenwich; vai de 0° a 180°, Leste ou Oeste.",["Longitude é o afastamento da linha do Equador; vai de 0° a 90°.","Longitude vai de 0° a 90°, Norte ou Sul."],"p. 48."],
["T12",49,"Latitude negativa indica ponto ao sul do Equador; longitude negativa indica ponto a oeste de Greenwich.",["Latitude negativa indica ponto ao norte do Equador.","Longitude negativa indica ponto a leste de Greenwich."],"Ex.: -22,326 (sul) e -42,669 (oeste), p. 49."],
["T12",48,"As coordenadas são obtidas pelo GPS integrado ao DMC.",["As coordenadas são informadas pelo produtor de memória.","As coordenadas são calculadas a partir do CEP."],"p. 48."],
["T12",49,"Nas áreas rurais, a captura das coordenadas dos estabelecimentos deve ser feita manualmente, com o recenseador posicionado no local correto.",["Nas áreas rurais, a captura é automática, sem necessidade de posicionamento.","Nas áreas rurais, as coordenadas são dispensadas."],"p. 49."],
["T12",49,"O local ideal de captura é a entrada da edificação que representa a sede do estabelecimento, caso haja.",["O local ideal de captura é o centro geométrico da propriedade.","O local ideal de captura é o posto censitário."],"Ponto de acesso à unidade (p. 49)."],
/* T13 */
["T13",51,"Data de referência indica o momento específico a que as informações devem se referir; período de referência é o intervalo de tempo considerado.",["Data de referência é o dia da entrevista.","Período de referência é o tempo de duração da entrevista."],"p. 51."],
["T13",51,"Na seção sobre estabelecimento, a apostila indica data de referência 31/12/2025 e período de referência de 01/01/2025 a 31/12/2025.",["A data de referência indicada é 01/01/2025.","O período de referência indicado é de 01/01/2026 a 31/12/2026."],"p. 51. Atenção: a p. 9 fala em dados do ano 2026 para coleta em 2027; nas questões sobre data/período, a apostila usa 31/12/2025."],
["T13",51,"Lojas, escolas, hospitais, igrejas e unidades domiciliares não fazem parte da coleta do Censo Agro.",["Escolas e igrejas fazem parte da coleta do Censo Agro.","Todos os domicílios rurais são recenseados no Censo Agro."],"p. 51."],
["T13",52,"Quintal com frutíferas, horta e animais apenas para lazer dos moradores não constitui unidade recenseável.",["Qualquer quintal com horta deve ser recenseado.","Quintal com galinhas é sempre estabelecimento agropecuário."],"p. 52."],
["T13",53,"Produção de subsistência é aquela voltada às necessidades vitais do produtor e de sua família, podendo parte ser vendida ou trocada.",["Produção de subsistência é a que se destina exclusivamente à venda.","Produção de subsistência não é recenseada."],"p. 53."],
["T13",53,"A classificação como unidade recenseável é feita pelo questionário de abordagem inicial, e não por decisão direta do recenseador.",["O recenseador decide, pela observação da cerca, se a propriedade é recenseável.","A classificação é feita pelo ACS antes da visita."],"p. 53. Pegadinha: não se decide 'olhando pela cerca'."],
["T13",54,"Criação de pássaros, cães e gatos não é considerada atividade agropecuária.",["Criação de cães é considerada atividade pecuária.","Criação de pássaros ornamentais é atividade agropecuária."],"p. 54."],
["T13",54,"Criação de animais para experiências de laboratório e produção de soros e vacinas não é atividade agropecuária.",["Criação de animais para produção de vacinas é atividade agropecuária.","Biotérios de laboratório são estabelecimentos agropecuários."],"p. 54."],
["T13",55,"Hortos, postos zootécnicos e estações experimentais são locais não recenseáveis.",["Estações experimentais são sempre recenseáveis.","Postos zootécnicos são estabelecimentos agropecuários comuns."],"p. 55."],
["T13",55,"Hotéis-fazenda e locais de lazer, conventos e igrejas, hospitais, asilos e orfanatos são locais não recenseáveis.",["Hotéis-fazenda são sempre recenseáveis.","Conventos com horta são estabelecimentos agropecuários."],"p. 55."],
["T13",55,"Escolas profissionalizantes, patronatos, prisões e reformatórios são locais não recenseáveis.",["Escolas agrícolas profissionalizantes são recenseáveis.","Prisões com lavoura são estabelecimentos agropecuários."],"p. 55."],
["T13",55,"O estabelecimento agropecuário independe de tamanho, forma jurídica, localização (rural ou urbana) e valor da produção.",["Só é estabelecimento agropecuário o que estiver na área rural.","Só é estabelecimento agropecuário o que tiver produção acima de um valor mínimo."],"p. 55."],
["T13",53,"Depois de caracterizado o estabelecimento, devem ser registrados todos os efetivos de animais, culturas e produtos, com finalidade de venda ou subsistência.",["Após caracterizado, registram-se apenas os produtos vendidos.","Após caracterizado, registra-se apenas a área total."],"p. 53."],
/* T14 */
["T14",55,"Lavoura temporária é a que nasce, cresce e é colhida no mesmo ano, precisando ser replantada; ex.: milho, feijão, arroz e soja.",["Lavoura temporária é a que produz por muitos anos sem replantio; ex.: café.","Soja é exemplo de lavoura permanente."],"p. 55."],
["T14",56,"Lavoura permanente é plantada uma vez e produz por muitos anos; ex.: café, laranja e uva.",["Lavoura permanente precisa ser replantada todo ano.","Feijão é exemplo de lavoura permanente."],"p. 56."],
["T14",56,"Horticultura é a produção de legumes, verduras, plantas medicinais, condimentares e cogumelos.",["Horticultura é a criação de peixes em tanques.","Cogumelos não fazem parte da horticultura."],"p. 56."],
["T14",56,"A hidroponia é um cultivo em outros meios, sem solo, com as raízes recebendo solução nutritiva.",["Hidroponia é a criação de animais em meio aquático.","Hidroponia é o cultivo em solo com irrigação por gotejamento."],"p. 56."],
["T14",56,"Criação de animais inclui criação, recriação ou engorda de animais de grande, médio e pequeno porte, inclusive abelhas.",["Abelhas não são consideradas na criação de animais.","Criação de animais inclui apenas animais de grande porte."],"p. 56."],
["T14",56,"Aquicultura é a criação de peixes, camarões, moluscos, jacarés e rãs.",["Jacarés e rãs não fazem parte da aquicultura.","Aquicultura é a pesca em rios naturais."],"p. 56. Pegadinha: jacarés e rãs entram."],
["T14",56,"Pesque-pague é estabelecimento agropecuário quando há criação e engorda de peixes; se só compra peixes já criados, não é.",["Todo pesque-pague é estabelecimento agropecuário.","Nenhum pesque-pague é estabelecimento agropecuário."],"p. 56."],
["T14",56,"Exploração de matas e florestas inclui plantio de árvores para celulose e coleta de frutos nativos como babaçu, açaí e buriti.",["A coleta de açaí nativo não é investigada.","Plantio de eucalipto para celulose não é atividade florestal."],"p. 56."],
/* T15 */
["T15",57,"Produtores sem área usam recursos naturais ou áreas disponíveis temporariamente; deve-se registrar a atividade e aplicar o questionário.",["Produtores sem área não são recenseados.","Para produtores sem área, registra-se apenas o nome."],"p. 57."],
["T15",57,"O produtor de mel que instala colmeias em matas ou em áreas de outros estabelecimentos é exemplo de produtor sem área.",["O apicultor com colmeias em área de terceiros é ignorado pelo Censo.","Apicultura não é atividade agropecuária."],"p. 57."],
["T15",57,"O extrativista que coleta babaçu, castanha-do-brasil, látex ou lenha em matas pode ser produtor sem área.",["Extrativistas nunca são produtores sem área.","Coleta de lenha não é registrada no Censo."],"p. 57."],
["T15",57,"Comodato é a situação em que o produtor usa a terra emprestada, sem pagar.",["Comodato é o arrendamento da terra mediante pagamento.","Comodato é a compra parcelada da terra."],"Nota 2 (p. 57). Pegadinha: arrendamento é pago."],
["T15",58,"Se o produtor que arrendou a terra (como o Sr. Jorge) não estava mais nela na data de referência, o recenseador deve localizá-lo, se possível, e marcar o item de produtor sem área.",["A produção do arrendatário que saiu deve ser registrada no nome do proprietário da terra.","A produção do arrendatário que saiu não deve ser registrada."],"Caso Sr. Mário/Sr. Jorge (p. 57–58)."],
/* T16 */
["T16",59,"Em estabelecimentos de indústrias, o Censo Agro investiga somente a parte diretamente ligada à atividade agropecuária, florestal e aquícola.",["Em estabelecimentos de indústrias, o Censo Agro investiga toda a produção industrial.","Estabelecimentos de indústrias nunca são recenseados."],"p. 59."],
["T16",59,"Boitel só é estabelecimento agropecuário se tiver animais próprios ou outra atividade agropecuária; animais de terceiros são contados nos estabelecimentos dos proprietários.",["No boitel, todos os animais confinados são contados no próprio boitel.","Boitel é sempre estabelecimento agropecuário."],"p. 59."],
["T16",60,"Nem toda propriedade rural é um estabelecimento agropecuário (ex.: sítios de lazer).",["Toda propriedade rural é um estabelecimento agropecuário.","Sítios de lazer são sempre recenseados."],"p. 60."],
["T16",60,"Uma única propriedade rural pode ter mais de um estabelecimento, quando diferentes produtores exploram partes distintas.",["Uma propriedade rural corresponde sempre a um único estabelecimento.","Vários produtores na mesma propriedade formam sempre um único estabelecimento."],"p. 60."],
["T16",60,"Mais de uma propriedade rural pode formar um único estabelecimento, quando o mesmo produtor explora áreas de diferentes proprietários.",["Propriedades de donos diferentes nunca formam um único estabelecimento.","Cada propriedade é sempre um estabelecimento distinto."],"p. 60."],
["T16",61,"Sede é o local destinado à administração dos trabalhos do estabelecimento, desde que esteja na área do estabelecimento.",["Sede é o escritório do produtor na cidade, fora do estabelecimento.","Sede é o posto censitário mais próximo."],"p. 61."],
["T16",61,"O estabelecimento que se estende por mais de um setor é recenseado no setor onde está a sua sede.",["O estabelecimento em mais de um setor é recenseado em todos os setores.","O estabelecimento em mais de um setor é recenseado no setor de menor área."],"p. 61."],
["T16",61,"Sem sede, o estabelecimento é recenseado no setor onde está a maior parte de suas terras.",["Sem sede, o estabelecimento é recenseado no setor visitado primeiro.","Sem sede, o estabelecimento não é recenseado."],"p. 61."],
["T16",61,"Se os setores forem de municípios distintos, toda a produção é computada no município onde está a sede.",["Se os setores forem de municípios distintos, a produção é dividida igualmente entre eles.","A produção é computada no município de residência do produtor, fora do estabelecimento."],"p. 61."],
["T16",61,"Áreas não contínuas formam um único estabelecimento se estiverem no mesmo município, usarem os mesmos recursos técnicos, o mesmo pessoal e a mesma administração.",["Áreas não contínuas formam um único estabelecimento se pertencerem ao mesmo dono, ainda que em municípios diferentes.","Basta usar o mesmo pessoal para que áreas não contínuas sejam um único estabelecimento."],"Quatro condições simultâneas (p. 61)."],
["T16",62,"Se qualquer uma das quatro condições não for atendida, a área é considerada outro estabelecimento.",["Basta atender a duas das quatro condições para formar um único estabelecimento.","As quatro condições são opcionais."],"p. 62."],
["T16",62,"Rios, estradas ou ferrovias cortando as terras não caracterizam descontinuidade da área.",["Uma estrada que corta a propriedade a divide em dois estabelecimentos.","Um rio cortando as terras torna a área não contínua."],"p. 62. Pegadinha muito cobrada."],
["T16",62,"Áreas totalmente localizadas em municípios diferentes são estabelecimentos diferentes, e o recenseador deve contatar o supervisor.",["Áreas em municípios diferentes formam um único estabelecimento se tiverem o mesmo dono.","Nessa situação o recenseador decide sozinho, sem acionar a supervisão."],"Situação 1 (p. 62)."],
["T16",63,"Um estabelecimento com 15,5 ha próprios e 4,5 ha arrendados contíguos é um único estabelecimento de 20 ha.",["15,5 ha próprios e 4,5 ha arrendados formam dois estabelecimentos.","Informa-se apenas a área própria, de 15,5 ha."],"Exemplo 1 (p. 63)."],
["T16",64,"Sucessão é a transmissão de direitos, obrigações e bens de uma pessoa para outra após a sua morte.",["Sucessão é a divisão de lucros entre sócios.","Sucessão é uma disputa judicial."],"p. 64. Partilha = divisão; litígio = disputa."],
["T16",65,"Havendo consenso entre herdeiros, o estabelecimento em sucessão ou partilha é recenseado como um único estabelecimento.",["Havendo consenso, cada herdeiro gera um estabelecimento.","Estabelecimentos em partilha não são recenseados."],"Situação 1 (p. 65). Informante: inventariante, representante legal ou condômino responsável."],
["T16",65,"Quando cada herdeiro ocupa uma parte do terreno, cada parte é um estabelecimento diferente.",["Mesmo ocupando partes separadas, os herdeiros formam um único estabelecimento.","Apenas a parte do herdeiro mais velho é recenseada."],"Situação 2 (p. 65)."],
["T16",65,"Em disputa judicial, considera-se produtor quem, na data de referência, era responsável economicamente pela exploração.",["Em disputa judicial, considera-se produtor quem tem o título da terra.","Em disputa judicial, o estabelecimento não é recenseado."],"p. 65."],
["T16",65,"Estabelecimentos novos ou sem produção no período de referência também devem ser recenseados, registrando o motivo em Observações.",["Estabelecimentos sem produção no período não são recenseados.","Estabelecimentos com perda por seca são excluídos."],"p. 65–66."],
["T16",66,"Na exploração comunitária com produção coletiva (famílias dividem a produção), preenche-se apenas um questionário.",["Na produção coletiva, preenche-se um questionário por família.","Na produção coletiva, não se preenche questionário."],"Situação 1 (p. 66)."],
["T16",66,"Na exploração comunitária com produção individual (cada família decide o que produzir), preenche-se um questionário por família.",["Na produção individual, preenche-se um único questionário para a comunidade.","Na produção individual, a comunidade não é recenseada."],"Situação 2 (p. 66)."]
];

/* cenários escritos à mão (estilo Cesgranrio): [tópico, dificuldade, enunciado, [A..E], correta(0-4), comentário] */
const IBGE_CEN=[
["T13","Médio","Em uma propriedade rural, a moradora informa que cria seis galinhas e cultiva uma pequena horta, apenas para o prazer de comer ovos e verduras frescas, sem venda e sem depender disso para a alimentação da família. De acordo com a apostila, o Recenseador deve:",["registrar a propriedade como estabelecimento agropecuário, pois há criação de animais","considerar que não há unidade recenseável, já que a produção é só para lazer dos moradores","registrar apenas as galinhas, por serem efetivo de animais","encaminhar o caso ao CNQ para decisão","registrar como produtor sem área"],1,"Produção apenas para deleite/lazer dos moradores não é recenseável (p. 52–54). Se a família dependesse dela para se alimentar (subsistência), seria recenseável."],
["T16","Difícil","O Sr. Antônio explora três glebas não contínuas no mesmo município, com o mesmo trator e os mesmos empregados. Uma das glebas, porém, é administrada de forma independente por seu sobrinho. Nesse caso:",["as três glebas formam um único estabelecimento","a gleba administrada pelo sobrinho é outro estabelecimento","nenhuma gleba é recenseada","as três glebas são três estabelecimentos, por serem não contínuas","o recenseador escolhe livremente como registrar"],1,"As quatro condições (mesmo município, mesmos recursos técnicos, mesmo pessoal, mesma administração) devem ser atendidas simultaneamente (p. 61–62). Faltando a administração única, aquela gleba é outro estabelecimento."],
["T16","Médio","Uma fazenda é cortada ao meio por uma rodovia estadual. A sede fica no lado norte. Como deve ser registrada?",["Como dois estabelecimentos, um de cada lado da rodovia","Como um único estabelecimento, pois estradas que cortam as terras não caracterizam descontinuidade","Apenas a parte norte, onde está a sede","Apenas a parte de maior área","Como produtor sem área"],1,"Rios, estradas ou ferrovias cortando as terras não caracterizam descontinuidade (p. 62)."],
["T16","Médio","Um estabelecimento ocupa terras de dois setores censitários do mesmo município. A sede, onde o produtor reside e administra o trabalho, está no setor B, mas a maior parte das terras está no setor A. O estabelecimento deve ser recenseado:",["no setor A, onde está a maior parte das terras","no setor B, onde está a sede","nos dois setores, dividindo a produção","no setor que for visitado primeiro","pelo ACS, fora da rota"],1,"Regra principal: setor da sede. A maior parte das terras só vale quando não há sede (p. 61)."],
["T15","Médio","O Sr. Mário arrendou sua terra ao Sr. Jorge durante todo o período de referência. Na data de referência, o Sr. Jorge já havia deixado a área. O Recenseador deve:",["registrar a produção do Sr. Jorge como se fosse do Sr. Mário","não registrar a produção do Sr. Jorge","localizar o Sr. Jorge, se possível, coletar as informações e marcar o item de produtor sem área","registrar o Sr. Jorge como produtor da propriedade do Sr. Mário","encerrar a coleta e informar ao AOR"],2,"Caso descrito nas p. 57–58."],
["T10","Fácil","Durante a entrevista, um informante se declara quilombola e também pescador artesanal. O Recenseador, achando estranho, deve:",["registrar apenas a identidade que considerar mais adequada","pedir um documento que comprove o pertencimento","registrar a declaração do informante, sem questionar, pois o pertencimento é autodeclaratório e pode ser múltiplo","consultar o ACS antes de registrar","registrar como não informado"],2,"Autodeclaração e multiplicidade de identidades (p. 40)."],
["T07","Fácil","Ao percorrer o setor, o Recenseador percebe que um córrego usado como limite secou e mudou de curso. Ele deve:",["ajustar o perímetro do setor ao novo curso do córrego","comunicar imediatamente a supervisão, sem alterar o perímetro","usar o limite que achar mais lógico","desconsiderar o limite e recensear até a próxima estrada","pedir ao produtor que indique o limite"],1,"O recenseador não pode alterar o perímetro em hipótese alguma; diante de dificuldade, comunica a supervisão (p. 30)."],
["T05","Fácil","O Recenseador encontra um estabelecimento agropecuário que não consta da lista prévia do DMC. Ele deve:",["ignorá-lo, pois a lista prévia é definitiva","incluí-lo na lista e realizar a visita e o registro","esperar a lista ser atualizada pelo posto","registrá-lo apenas se o produtor pedir","excluir outro endereço para manter o total"],1,"Deve visitar todos os endereços, mesmo fora da lista, incluindo os novos (p. 21 e 27)."],
["T11","Médio","Um Recenseador registrou o ponto de referência 'Casa do Seu Zé, depois da porteira'. O registro está:",["correto, pois facilita a localização","incorreto, pois não é permitido identificar pessoas nos componentes do endereço","correto, desde que o Seu Zé autorize","incorreto, pois pontos de referência são proibidos em áreas rurais","correto, se o endereço não tiver número"],1,"Identificar pessoas fere o sigilo estatístico (p. 47)."],
["T13","Médio","Um pesque-pague apenas compra peixes já criados de outros produtores e os solta nos tanques para os clientes pescarem. Ele é:",["estabelecimento agropecuário, por ter peixes","estabelecimento aquícola, por ter tanques","não considerado estabelecimento agropecuário, pois não há criação e engorda","estabelecimento florestal","produtor sem área"],2,"Só é estabelecimento se houver criação e engorda de peixes (p. 56)."],
["T16","Médio","Uma comunidade indígena trabalha junta em uma mesma roça e divide a produção entre as famílias. Quantos questionários devem ser preenchidos?",["Um por família","Um para cada roça","Apenas um questionário","Nenhum, por ser terra indígena","Um por pessoa adulta"],2,"Produção coletiva: um questionário (p. 66). Se cada família decidisse sua produção, seria um por família."],
["T09","Difícil","Em um setor, há 18 indivíduos autodeclarados quilombolas morando em moradias contíguas, com vínculos familiares. Pela apostila, esse setor pode ser do tipo:",["Agrovila","Agrupamento Quilombola","Setor com Baixo Patamar Domiciliar","Quartel e Base Militar","Não especial, pois exige 50 pessoas"],1,"Agrupamento Quilombola: 15 ou mais indivíduos autodeclarados (p. 38). O número 50 vale para quartel, alojamento, prisão etc."],
["T06","Médio","Em um mapa na escala 1:25.000, dois estabelecimentos estão a 6 cm um do outro. A distância real é de:",["150 m","1,5 km","15 km","2,5 km","600 m"],1,"6 × 25.000 = 150.000 cm = 1.500 m = 1,5 km."],
["T12","Fácil","Um ponto tem latitude -5,18 e longitude -40,67. Esse ponto está:",["ao norte do Equador e a leste de Greenwich","ao sul do Equador e a oeste de Greenwich","ao norte do Equador e a oeste de Greenwich","ao sul do Equador e a leste de Greenwich","sobre a linha do Equador"],1,"Negativo na latitude = Sul; negativo na longitude = Oeste (p. 49)."],
["T04","Fácil","Durante a coleta, o Recenseador tem dúvida sobre como registrar uma situação especial. Ele deve recorrer primeiramente:",["ao AOR","ao ACI","ao ACS","ao Analista Censitário Nacional","ao informante"],2,"É ao ACS que o Recenseador se reporta (p. 18)."],
["T03","Médio","O servidor que gerencia o posto censitário e garante que as instruções operacionais, técnicas e administrativas sejam observadas é o:",["ACS","ACR","AOR","ACA","ACQ"],2,"AOR (p. 15)."],
["T16","Médio","Três irmãos herdaram uma fazenda. O inventário não terminou, mas eles concordam em manter a exploração conjunta. Como recensear?",["Três estabelecimentos, um por irmão","Um único estabelecimento, informado pelo inventariante, representante legal ou condômino responsável","Não recensear até o fim do inventário","Recensear apenas a parte do irmão mais velho","Recensear como produtor sem área"],1,"Consenso entre herdeiros → um único estabelecimento (p. 65)."],
["T13","Fácil","Qual dos locais abaixo é recenseável, segundo a apostila?",["Hotel-fazenda com pomar para hóspedes","Estação experimental de pesquisa agrícola","Sítio que produz mandioca e vende a farinha na feira","Convento com horta","Penitenciária com lavoura"],2,"Produção para venda é recenseável; os demais são locais excluídos (p. 55)."],
["T14","Fácil","Assinale a alternativa que apresenta apenas lavouras temporárias:",["café, laranja e uva","milho, feijão e soja","arroz, café e uva","laranja, soja e milho","uva, feijão e café"],1,"Temporárias: milho, feijão, arroz, soja. Permanentes: café, laranja, uva (p. 55–56)."],
["T08","Médio","No geocódigo 23 12804 05 00 0031, o código do município é:",["23","12804","05","00","0031"],1,"Estrutura: UF (23) + município (12804) + distrito (05) + subdistrito (00) + setor (0031)."],
["T11","Médio","No endereço 'Rodovia BR-230, 58 KM, lote 9', o termo 'KM' corresponde ao:",["logradouro","número","modificador","complemento","ponto de referência"],2,"Exemplo da p. 46: 58 = número; KM = modificador; lote 9 = complemento."],
["T09","Médio","Uma aglomeração de casas fica a 600 m da cidade e tem características de loteamento. Pela apostila, trata-se de:",["aglomerado rural","núcleo urbano","área rural de ocupação dispersa","massa d'água","agrovila"],1,"Núcleo urbano: separado por menos de 1 km ou com características urbanas (p. 36)."],
["T10","Médio","Em um setor coberto por uma Área de Interesse Operacional (AIO) de povos tradicionais, o Recenseador:",["deve desenhar a AIO no DMC","verá a AIO carregada automaticamente no mapa digital e perguntas específicas no DMC","deve excluir o setor da coleta","deve coletar somente em papel","deve pedir autorização à prefeitura"],1,"p. 41."],
["T07","Médio","O item 'Setores a serem excluídos' do Descritivo indica:",["setores sem produção agropecuária","setores contidos no perímetro do seu setor que não são de sua responsabilidade","setores que já foram recenseados em 2017","setores onde o acesso é proibido","setores que o recenseador pode escolher não visitar"],1,"p. 30."],
["T16","Difícil","Um boitel confina 800 bois de terceiros e não possui animais próprios nem outra atividade agropecuária. Pela apostila:",["o boitel é estabelecimento agropecuário com 800 bois","o boitel não é estabelecimento agropecuário, e os bois são contados nos estabelecimentos de seus proprietários","os bois não são contados em lugar nenhum","os bois são contados metade no boitel e metade nos proprietários","o boitel é produtor sem área"],1,"p. 59."],
["T16","Fácil","Um sítio teve toda a lavoura de feijão perdida pela seca no período de referência. Ele deve ser:",["excluído da coleta","recenseado, registrando em Observações o motivo da ausência de produção","recenseado como produtor sem área","recenseado apenas se tiver animais","transferido para o próximo censo"],1,"p. 65–66."],
["T05","Fácil","Para planejar como chegar ao seu setor, o Recenseador deve consultar principalmente:",["o Manual do Recenseador","o Mapa Municipal Estatístico (MME) fixado no posto","o questionário","a lista de endereços","o CEP do setor"],1,"p. 20."],
["T04","Médio","Gerir e responder alertas no Sistema de Indicadores de Desempenho (SIGC) é atribuição do:",["Recenseador","ACS","ACI","ACA","Analista Censitário Nacional"],1,"p. 17. O ACR também 'gere e responde alertas no sistema' (p. 16), mas o SIGC é citado nominalmente nas atribuições do ACS."],
["T12","Médio","O local ideal para capturar as coordenadas de um estabelecimento rural é:",["o centro da maior lavoura","a entrada da edificação que representa a sede, caso haja","a porteira mais distante","qualquer ponto dentro do setor","o posto censitário"],1,"Ponto de acesso à unidade (p. 49)."],
["T02","Médio","Assinale a sequência correta de anos de Censos Agropecuários:",["1920, 1940, 1950, 1960, 1970, 1975, 1980, 1985, 1996, 2006, 2017","1920, 1940, 1950, 1960, 1970, 1975, 1980, 1985, 1996, 2007, 2017","1920, 1936, 1946, 1956, 1966, 1976, 1986, 1996, 2007, 2017","1920, 1940, 1950, 1960, 1970, 1980, 1990, 2000, 2010, 2017","1936, 1940, 1950, 1960, 1970, 1975, 1980, 1985, 1990, 2007, 2017"],1,"1920; decenais 1940–1970; quinquenais 1975, 1980, 1985; sem 1990; 1996; 2007; 2017 (p. 8)."]
];

/* cards de estudo: [tópico, título, texto] — cobrem toda a apostila */
const IBGE_CARDS_TEC=[
["T01","IBGE em 1 minuto","Fundado em 1936. Órgão coordenador e produtor de informações estatísticas e geográficas. Missão: “retratar o Brasil com informações necessárias ao conhecimento de sua realidade e ao exercício da cidadania”. Rede: 27 Superintendências Estaduais (26 nas capitais + 1 no DF) e 566 agências, todas vinculadas à Presidência."],
["T02","Linha do tempo do Censo Agro","1920 (1º censo) → 1936 (IBGE) → 1940, 1950, 1960, 1970 (decenais) → 1975, 1980, 1985 (quinquenais) → 1990 NÃO houve → 1996 → 2007 → 2017 → 12º Censo: coleta em 2027.\nPegadinha: 2006 e 2016 não existem; 1990 não aconteceu."],
["T02","O que é um censo","Censo coleta dados de TODO o universo (não é amostra). No Censo Agro, o universo é o dos estabelecimentos agropecuários. Agropecuário = agricultura + pecuária. Florestal = matas nativas ou plantadas e extrativismo. Aquícola = vida total ou parcialmente em meio aquático."],
["T02","Objetivos, concepção e impactos","Levantar informações de TODOS os estabelecimentos do país (≈ 5,1 milhões). Comparar com censos anteriores, estratificar por tipologias (agricultura familiar, patronal, PCTs), produzir edições digitais e criar cadastro para pesquisas amostrais. Concepção: recomendações da FAO. Abrangência: municípios, Terras Indígenas, Unidades de Conservação, Territórios Quilombolas, Biomas, Assentamentos. Impacto: avaliar políticas como o Pronaf."],
["T03","Estrutura permanente × temporária","PERMANENTE: Sede (diretorias, coordenações) + Superintendências Estaduais, ligadas à Presidência. Organograma: Presidência → DGC, DPE (→ COAGRO), SES.\nTEMPORÁRIA: CNQ (ligado à Sede, nível nacional), CEQ (ligado às SES, nível estadual) e Postos censitários. Cerca de 36 mil temporários em 2027."],
["T04","Quem é quem no posto","AOR: gere o posto. ACA: apoio administrativo ao AOR. ACI: apoio de TI ao AOR. ACR: subordinado ao AOR, gerencia os ACS, cobertura e prazos. ACS: supervisiona e treina Recenseadores; elo entre quem coleta e quem gerencia; alertas no SIGC. Recenseador: coleta presencial em rotas diárias, sob supervisão do ACS.\nQualidade: Analista Nacional/Estadual e ACQ."],
["T04","Atribuições do Recenseador","Coletar conforme os manuais; ir a campo todo dia seguindo a rota; abordar e entrevistar; registrar e transmitir dados (fotos, parcelas, coordenadas, questionários); agendar entrevistas se o informante pedir; zelar pelo DMC; zelar pela confidencialidade. Dúvida? Fala com o ACS. Supervisão pediu correção? Volta a campo."],
["T05","Instrumentos de trabalho","1) Mapa do Setor: área a recensear; no verso, a descrição dos limites. 2) Descritivo do setor: texto do contorno. 3) MME: fixado no posto, mostra todos os setores do município e acessos — use para planejar a CHEGADA. 4) DMC (tablet): mapa digital, Lista de Endereços (lista prévia) e questionários. 5) Manual do Recenseador."],
["T05","Lista prévia: 3 verbos","CONFIRMAR o que existe, INCLUIR o novo, EXCLUIR o que não foi encontrado. E visitar TODOS os estabelecimentos do setor, mesmo os que não estão na lista."],
["T06","Escala sem medo","Escala 1:X → 1 cm no mapa = X cm no terreno. Divida por 100 para metros e por 100.000 para km.\n1:50.000 → 1 cm = 500 m. 3 cm = 1,5 km (≈ 20 min a pé).\n1:10.000 → 1 cm = 100 m. 1:25.000 → 1 cm = 250 m.\nTruque: medir com os dedos na escala gráfica e transferir para o mapa."],
["T06","Lendo a imagem de satélite","Forma (rotatória = círculo), Tamanho (galpão > casa), Localização (estradas acompanham rios, ligam propriedades), Cores (pasto verde; telhados vermelho, laranja, cinza ou branco). E sempre: legenda antes de interpretar qualquer símbolo. GPS ajuda, mas não substitui o mapa nem a sua interpretação."],
["T07","Descritivo: as 5 partes","1) Ponto inicial e final (de fácil acesso; se mudar, avise o Supervisor). 2) Descrição do perímetro. 3) Setores a serem excluídos (outro recenseador cuida). 4) Estruturas territoriais não setorizadas (aglomerados pequenos: recenseie normalmente, com atenção). 5) Acessibilidade e observações (ex.: acesso fluvial)."],
["T07","Tipos de limite","A) Corpos hídricos (rios, córregos, igarapés, lagoas). B) Rodovias, estradas e ferrovias, asfaltadas ou não. C) Caminhos, ramais e estradas secundárias. D) Linhas secas: retas não materializadas no terreno (ex.: faixa de 10 km ao norte de um rio).\nREGRA DE OURO: o recenseador NUNCA altera o perímetro."],
["T08","Brasil em números (2025)","26 estados + 1 Distrito Federal + 1 Distrito Estadual (Fernando de Noronha). 5.569 municípios (criados por lei ESTADUAL). 10.744 distritos (lei MUNICIPAL, sem autonomia). ≈ 645 subdistritos (grandes cidades). Menor unidade: setor censitário."],
["T08","Geocódigo: 15 dígitos","UF (2) | Município (5) | Distrito (2) | Subdistrito (2) | Setor (4).\nEx.: 51 04104 05 00 0016 → UF 51, município 04104, distrito 05, subdistrito 00, setor 0016. Aparece no título e rodapé dos mapas e no canto superior direito do Descritivo."],
["T09","Situação × Tipo","SITUAÇÃO: urbano ou rural (forma de ocupação). Rural: aglomerado rural (casas a até 50 m entre si, a mais de 1 km da cidade) ou área rural dispersa. Urbana: alta densidade, baixa densidade ou núcleo urbano (a menos de 1 km da cidade ou com cara urbana). Massa d'água: não é área de coleta.\nTIPO: especificidades do território (acesso, procedimento)."],
["T09","Tipos de setor e seus números","Não especial. Quartel/Base Militar: ≥ 50 hab. há +1 ano. Alojamento/Acampamento: ≥ 50 hab. há +1 ano. Baixo Patamar Domiciliar: poucos ou nenhum domicílio. Agrupamento Indígena: ≥ 15 indígenas. Unidade prisional: > 50 presos. Convento/Hospital/ILPI/IACA: > 50 hab. há +1 ano. Agrovila: > 50 domicílios de assentamento. Agrupamento Quilombola: ≥ 15 quilombolas.\nSó são visitados no Censo Agro se tiverem produção."],
["T10","Povos e Comunidades Tradicionais","Grupos culturalmente diferenciados que se reconhecem como tais. Exemplos: indígenas, quilombolas, ciganos, pescadores artesanais, extrativistas (raizeiros, quebradeiras de coco-babaçu, catadores de mangaba…), caiçaras, caatingueiros, vazanteiros, pantaneiros, retireiros, morroquianos, fundos e fechos de pasto.\nAutodeclaração, sem questionar. Pode haver mais de uma identidade."],
["T10","Categorias, AIOs e acesso","Oficialmente reconhecidos pelo Estado: Terras Indígenas, Territórios Quilombolas, Unidades de Conservação, parte dos Assentamentos. Identificados pelo IBGE: Agrupamentos Indígenas e Quilombolas. Para a operação: AIOs (não seguem a setorização; carregam sozinhas no DMC). Acesso negociado com lideranças (Convenção 169 da OIT). 67,1% dos indígenas em TIs falam português no domicílio; guia-intérprete indicado com FUNAI e SESAI."],
["T11","Endereço CNEFE","Logradouro (sem abreviar; pode ser estrada, rodovia, travessa, acesso ou rio) · Localidade (povoado, assentamento; na cidade ≈ bairro) · CEP (8 dígitos, Correios) · Número e Modificador (4573 B; 58 KM) · Complemento (lote, gleba, casa, fundos) · Ponto de referência (obrigatório sem número/complemento; nunca redundante) · Coordenadas.\nPROIBIDO identificar pessoas."],
["T12","Latitude e longitude","LATITUDE: a partir do Equador, 0° a 90°, Norte (+) ou Sul (−). Linhas horizontais.\nLONGITUDE: a partir de Greenwich, 0° a 180°, Leste (+) ou Oeste (−). Linhas verticais.\nNo Brasil, quase tudo é negativo nos dois (sul e oeste). Na área rural, a captura é manual, na entrada da sede."],
["T13","Recenseável ou não?","Pergunta-chave: há produção para VENDA/TROCA ou SUBSISTÊNCIA? Sim → recenseável. Só lazer/deleite → não.\nNunca recenseáveis: pássaros, cães, gatos; animais de laboratório/soros/vacinas; hortos, postos zootécnicos e estações experimentais; hotéis-fazenda; conventos e igrejas; hospitais, asilos e orfanatos; escolas profissionalizantes e patronatos; prisões e reformatórios.\nQuem decide é o questionário de abordagem inicial, não o olho do recenseador."],
["T13","Referência no tempo","Data de referência: o momento a que as informações se referem. Período de referência: o intervalo considerado. Na apostila (p. 51): data 31/12/2025 e período de 01/01/2025 a 31/12/2025.\nAtenção: a p. 9 diz que a coleta será em 2027 com dados de 2026. Se a questão citar data/período de referência, use o que a apostila diz na seção de Estabelecimento."],
["T14","Atividades que contam","Lavoura temporária (colhe e replanta: milho, feijão, arroz, soja). Lavoura permanente (planta uma vez: café, laranja, uva). Horticultura (legumes, verduras, medicinais, condimentares, cogumelos). Hidroponia. Criação de animais (grande, médio e pequeno porte, abelhas). Aquicultura (peixes, camarões, moluscos, jacarés, rãs). Matas e florestas (celulose, açaí, babaçu, buriti).\nPesque-pague só conta se cria e engorda."],
["T15","Produtor sem área","Quem produz sem área própria ou delimitada: mel em matas de terceiros, extrativista (babaçu, castanha, látex, lenha), criador em beira de estrada, quem produziu (em terra própria, arrendada, em comodato, parceria ou ocupada) mas já saiu da terra na data de referência. Aplica o questionário e marca o item de produtor sem área.\nComodato = terra emprestada, sem pagar."],
["T16","Sede, setores e municípios","Sede = onde se administra o estabelecimento (muitas vezes a casa do produtor), dentro da área. Em mais de um setor → recenseia no setor da SEDE. Sem sede → setor com a MAIOR PARTE das terras. Municípios diferentes → toda a produção no município da sede."],
["T16","Áreas não contínuas: as 4 condições","Para serem UM estabelecimento, TODAS juntas: 1) mesmo município; 2) mesmos recursos técnicos (máquinas, animais de trabalho); 3) mesmo pessoal; 4) mesma administração. Faltou uma → outro estabelecimento.\nRio, estrada ou ferrovia cortando a terra NÃO a torna descontínua. Áreas em municípios diferentes: contate o supervisor."],
["T16","Herança, novos e comunitários","Sucessão = transmissão após a morte. Partilha = divisão. Litígio = disputa judicial. Herdeiros de acordo → 1 estabelecimento (informa o inventariante, representante ou condômino). Cada herdeiro em sua parte → 1 por parte. Disputa → produtor é quem respondia economicamente na data de referência.\nNovos ou sem produção (pés novos, perda por clima) → recenseia e explica em Observações.\nComunitária: coletiva = 1 questionário; individual = 1 por família."],
["T16","Indústria, boitel e propriedade","Indústria com área agro: só a parte agropecuária entra. Boitel: só é estabelecimento se tiver animais próprios ou outra atividade; boi de terceiro conta no estabelecimento do dono.\nPropriedade ≠ estabelecimento: nem toda propriedade é estabelecimento (sítio de lazer); uma propriedade pode ter vários (vários produtores); várias propriedades podem formar um (mesmo produtor arrendando de vários donos)."]
];
